using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Drawing;
using System.Collections.Generic;
using System.Web.Script.Serialization;
class MonitorV519Tests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static string Payload(DateTime now,int primary=300,int secondary=10080,double used=85){long reset=(long)(now.AddHours(4)-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds;return "{\"rateLimits\":{\"primary\":{\"windowDurationMins\":"+primary+",\"usedPercent\":"+used.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"resetsAt\":"+reset+"},\"secondary\":{\"windowDurationMins\":"+secondary+",\"usedPercent\":65,\"resetsAt\":"+reset+"}}}";}
 [STAThread]static int Main(string[] args){try{
 var now=DateTime.UtcNow;var quota=CodexQuotaSnapshot.Parse(Payload(now),now);Check(quota.Remaining(300,now)==15&&quota.Remaining(10080,now)==35,"used converted to separate remaining windows");var swapped=CodexQuotaSnapshot.Parse(Payload(now,10080,300),now);Check(swapped.Remaining(10080,now)==15&&swapped.Remaining(300,now)==35,"windows assigned by duration not field position");Check(!quota.Remaining(300,now.AddMinutes(6)).HasValue,"stale quota not shown as current");quota.Windows[0].ResetUtc=now;Check(!quota.Remaining(300,now).HasValue,"reset quota unknown until fetched again");quota=CodexQuotaSnapshot.Parse(Payload(now),now);var reader=new CodexQuotaReader();var config=new CodexQuotaConfig();Check(reader.Alerts(quota,config,now).Length==1,"low five hour quota generates warning");Check(reader.Alerts(quota,config,now).Length==0,"same window warning deduplicated");config.WeeklyThreshold=40;Check(reader.Alerts(quota,config,now).Length==1,"weekly threshold independently adjustable");Check(reader.Alerts(quota,config,now.AddMinutes(6)).Length==0,"stale quota cannot alarm");config.Alerts=false;Check(reader.Alerts(quota,new CodexQuotaConfig{Alerts=false},now).Length==0,"disabled quota alarms silent");
 var c=new MonitorConfig();Check(c.RefreshMilliseconds==1000,"default sampling matches TrafficMonitor 1000 ms");c.TaskbarItems=new List<string>{"cpu","memory","disk","cpuTemp","gpu","gpuTemp"};c.Appearance.AutoRows=false;c.Appearance.ItemGap=37;c.Appearance.EqualColumns=true;var sample=new SystemSample{Cpu=52,MemoryUsed=8,MemoryTotal=16,Gpu=42,DiskBusy=17,CpuTemperature=61,GpuTemperature=51,Quota=quota};var g=TaskbarPainter.Geometry(c,1,100,sample);Check(g.Rows==2,"two explicit rows preserved");Check(Math.Abs(g.Cells[2].Left-g.Cells[0].Right-37)<.1&&Math.Abs(g.Cells[4].Left-g.Cells[2].Right-37)<.1,"disk GPU column gap is exact user value");Check(g.Cells.Select(x=>x.Width).Distinct().Count()==1,"columns evenly distributed");Check(g.Values[0].Left==g.Values[1].Left&&g.Values[2].Left==g.Values[3].Left,"both row values align within each column");c.Appearance.ItemGap=120;c.Appearance.Validate();Check(TaskbarPainter.Geometry(c,1,100,sample).Size.Width>g.Size.Width,"wide column slider range applied");var legacy=new TaskbarAppearance();legacy.Items=legacy.Items.Take(8).ToList();legacy.Validate();Check(legacy.Items.Count==10,"eight item configurations migrated without reset");c.TaskbarItems.AddRange(new[]{"codex5h","codex7d"});new MonitorEngine(c);Check(c.TaskbarItems.Contains("codex5h")&&c.TaskbarItems.Contains("codex7d"),"quota selections survive config normalization");Check(TaskbarPainter.Format(sample,"codex5h",c.Appearance)=="15%","taskbar displays remaining quota");c.Appearance.AutoTheme=false;c.Appearance.ValueColor="#12AB34";Check(c.Appearance.Foreground(false)==TaskbarAppearance.ParseColor("#12AB34"),"custom taskbar foreground used");
 Check(NetworkExit.Proxy("direct","")==null,"explicit direct route supported");Check(NetworkExit.Proxy("manual","http://127.0.0.1:7890")!=null,"manual proxy supported");bool bad=false;try{NetworkExit.Proxy("manual","http://user:secret@localhost:7890");}catch(ArgumentException){bad=true;}Check(bad,"credential embedded proxy rejected");Check(NetworkExit.Failure(new System.Net.WebException("",System.Net.WebExceptionStatus.Timeout)).Contains("超时"),"timeout distinguished from unavailable data");
 if(args.Contains("--live")){var live=CodexQuotaReader.Fetch("");Check(live.Windows.Count>0&&live.Windows.All(x=>x.Remaining>=0&&x.Remaining<=100),"live official Codex rate limit query");var timer=Stopwatch.StartNew();using(var t=new Telemetry()){var times=new List<double>();for(int i=0;i<5;i++){var start=timer.Elapsed.TotalMilliseconds;var s=t.Sample(25,8,16);times.Add(timer.Elapsed.TotalMilliseconds-start);if(i>0)Check(s.Utc>now,"telemetry supplies advancing timestamps");System.Threading.Thread.Sleep(500);}Check(times.Skip(1).Max()<500,"steady samples do not block on GPU subprocess");}var exit=NetworkExit.Fetch();Check(!String.IsNullOrEmpty(exit.CountryCode)&&exit.CheckedUtc>now,"live exit country and check time valid without IP logging");}
 using(var image=TaskbarPainter.Preview(c,sample,100))image.Save(Path.Combine(args[0],"taskbar-even-columns.png"));
 }catch(Exception e){failures++;Console.WriteLine(e.GetType().Name+" "+e.Message);}Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"v519-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures}));return failures==0?0:1;}
}
